changeSet.sql:
INSERT INTO permissions (name, description)
VALUES ('plugin_devicelocation_access', 'Can see device locations on the map');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE id IN (1, 2);

INSERT INTO permissions (name, description)
VALUES ('plugin_devicelocation_settings', 'Can change device tracking settings');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE id IN (1, 2);

INSERT INTO permissions (name, description)
VALUES ('plugin_devicelocation_lost', 'Can report a device lost, which tracks it closely');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE id IN (1, 2);

CREATE TABLE plugin_devicelocation_point ( id SERIAL NOT NULL CONSTRAINT plugin_devicelocation_point_pr_key PRIMARY KEY, deviceId INT NOT NULL REFERENCES devices (id) ON DELETE CASCADE, customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE, lat DOUBLE PRECISION NOT NULL, lon DOUBLE PRECISION NOT NULL, ts BIGINT NOT NULL, whileLost BOOLEAN NOT NULL DEFAULT FALSE ); CREATE INDEX plugin_devicelocation_point_device_idx ON plugin_devicelocation_point (deviceId, ts DESC); CREATE UNIQUE INDEX plugin_devicelocation_point_uniq ON plugin_devicelocation_point (deviceId, ts);
CREATE TABLE plugin_devicelocation_lost ( deviceId INT NOT NULL CONSTRAINT plugin_devicelocation_lost_pr_key PRIMARY KEY REFERENCES devices (id) ON DELETE CASCADE, customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE, reportedAt BIGINT NOT NULL, reportedBy VARCHAR(100), note TEXT );
CREATE TABLE plugin_devicelocation_settings ( id SERIAL NOT NULL CONSTRAINT plugin_devicelocation_settings_pr_key PRIMARY KEY, customerId INT NOT NULL UNIQUE REFERENCES customers (id) ON DELETE CASCADE, keepPoints INT NOT NULL DEFAULT 5, normalIntervalMins INT NOT NULL DEFAULT 360, lostIntervalMins INT NOT NULL DEFAULT 2, tileUrl TEXT NOT NULL DEFAULT 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', tileAttribution TEXT NOT NULL DEFAULT '© OpenStreetMap contributors' );
INSERT INTO plugin_devicelocation_settings (customerId) SELECT id FROM customers;
